"""Render docs/reference/architecture-entity-design.md — the SDEM Architecture Entity Design: every architecture and entity type,
with source reference, verification, reasoning and confidence, and the design decisions behind them.

Generated from the entity catalogue (metamodel/a1…a4-*.json); the test suite checks it is current.
"""
from pathlib import Path
from collections import Counter
import argparse, json
from sdem.metamodel import Metamodel, MM_DIR, LEVEL_FILES
from sdem.terms import apply as _terms

DOC = MM_DIR.parent / 'docs' / 'reference' / 'architecture-entity-design.md'
NAMES = {'A1': 'A1 Business Architecture', 'A2': 'A2 Service Domain Architecture', 'A3': 'A3 Application Architecture', 'A4': 'A4 Technology Architecture'}
SOURCE = {'bian_reference': 'BIAN reference', 'bian_aligned': 'aligned to BIAN', 'archimate_native': 'ArchiMate native', 'archimate_aligned': 'aligned to ArchiMate',
          'togaf_informed': 'TOGAF-informed', 'sdem_extension': 'SDEM extension', 'sdmm_extension': 'SDEM extension', 'bank_extension': 'institution extension'}
STATUS = {'confirmed_in_official_source': 'concept confirmed', 'pending_release_validation': 'pending BIAN release validation',
          'interpreted_from_official_source': 'interpreted from source', 'proposed_extension': 'SDEM proposal'}


def render():
    ents = [e for f in LEVEL_FILES for e in json.loads((MM_DIR / f).read_text(encoding='utf-8'))['entities']]
    conf = Counter(e['confidence'] for e in ents); src = Counter(SOURCE[e['definition_source']] for e in ents)
    by = {l: [e for e in ents if e['level'] == l] for l in ('A1', 'A2', 'A3', 'A4')}
    lvl_std = {'A1': 'ArchiMate 3.2 Strategy, Business and Motivation (ch. 6–8), with BIAN\'s Business Capability Model', 'A2': 'BIAN Service Landscape 14.0 and the Semantic API Practitioner Guide v8.1',
               'A3': 'ArchiMate 3.2 Application (ch. 9), BIAN\'s Semantic API and OpenAPI for API operations, TOGAF 10 for the Solution Building Block', 'A4': 'ArchiMate 3.2 Technology (ch. 10), with three SDEM extensions'}
    out = ['# SDEM Architecture Entity Design', '',
           'Generated by `python -m sdem.catalogue` from the entity catalogue (`metamodel/a1…a4-*.json`); the test suite checks it is current. Part of the **Architecture Metamodel**: this document defines *which kinds of thing exist* in each of the four architectures, where each one comes from, why it is defined as it is, and how confident that basis is. The links allowed between them are in [`relationships-planning.md`](relationships-planning.md); the overview is [`sdem-overview.md`](sdem-overview.md).', '',
           '## 1. Design principles', '',
           '1. **Every entity type comes from a published reference architecture, or says that it does not.** No entity is named after, defined by or copied from an institution\'s model (README › *Reference architecture provenance*).',
           '2. **One concept, one entity.** Where a standard defines the concept exactly, SDEM uses it unchanged and names the standard and chapter.',
           '3. **Extensions are explicit.** Where SDEM needs something no standard defines, the entity is marked as an SDEM extension, names the standard concept it builds on, and records why.',
           '4. **Artefacts are documents, not things.** BIAN\'s Business Object Model, wireframes and Semantic APIs are citable as evidence but never instantiated or used as a relationship end.',
           '5. **Abstract types exist only for typing.** `A4.InfrastructureComponent` lets a relationship type target "any infrastructure"; it is never instantiated.', '',
           '## 2. How source, verification and confidence are recorded', '',
           '| Field | Meaning |', '|---|---|',
           '| Source reference | standard, release, concept, locator (chapter or page) and link, from the entity record |',
           '| Source type | how the entity relates to the standard: native or reference (exact), aligned (interpreted), informed (TOGAF, gated), or SDEM extension; with the alignment kind |',
           '| Verification | what has been checked: BIAN concepts against the public portal (**a licensed release is still pending**); ArchiMate concepts against the open-source Archi implementation of the relationship tables, because the specification text is login-gated; SDEM extensions are SDEM definitions, reviewed with the model |',
           '| Reasoning | why the entity is defined this way and how its source supports it |',
           '| **Confidence** | one rule for every layer of the model (`sdem/confidence.py`): **high** — defined by a public standard and checked; **medium** — built on a standard concept as SDEM chose to model it, or BIAN intent only, or an SDEM / gated / unverified basis that was validated against sealed answers; **low** — no standard basis and not validated |', '| Confidence basis | which part of the rule applied |', '',
           '## 3. Summary', '', '| Architecture | Built on | Entity types | High | Medium | Low |', '|---|---|---|---|---|---|']
    for l in ('A1', 'A2', 'A3', 'A4'):
        c = Counter(e['confidence'] for e in by[l])
        out.append(f"| {NAMES[l]} | {lvl_std[l]} | {len(by[l])} | {c['high']} | {c['medium']} | {c['low']} |")
    out += [f"| **All** | | **{len(ents)}** | **{conf['high']}** | **{conf['medium']}** | **{conf['low']}** |", '',
            '| Source type | Entity types |', '|---|---|'] + [f"| {k} | {v} |" for k, v in src.most_common()] + ['']
    n = 3
    for lvl in ('A1', 'A2', 'A3', 'A4'):
        rows = [e for e in ents if e['level'] == lvl]
        n += 1
        out += [f"## {n}. {NAMES[lvl]}", '', f"Built on {lvl_std[lvl]}.", '', '| Entity | Kind | Source reference | Source type | Verification | Reasoning | Confidence | Confidence basis |', '|---|---|---|---|---|---|---|---|']
        for e in rows:
            r = e['reference']; kind = 'abstract' if e['abstract'] else 'artefact' if e['artefact'] else 'concrete'
            if e.get('extends'): kind += f", extends `{e['extends']}`"
            std = r['standard'] if r['release'] in r['standard'] else f"{r['standard']} {r['release']}"
            ref = f"{std}: *{r['concept']}*" + (f", {r['locator']}" if r.get('locator') else '') + f" ([link]({r['uri']}))"
            out.append(f"| `{e['type']}` | {kind} | {ref} | {SOURCE[e['definition_source']]} ({e['alignment_kind']}) | {STATUS.get(e['evidence_status'], e['evidence_status'])} | {e['reasoning']} | **{e['confidence']}** | {e.get('confidence_basis', '')} |")
        out.append('')
    weak = [e for e in ents if e['confidence'] != 'high']
    out += [f'## {n + 1}. Entities SDEM defines or interprets', '',
            f'These {len(weak)} entity types are SDEM design decisions rather than one-to-one standard concepts. Each is reasoned above; together with the attribute sources in [`inference-audit.md`](inference-audit.md) they are what a blind reviewer should challenge first.', '',
            '| Entity | Confidence | Built on |', '|---|---|---|']
    out += [f"| `{e['type']}` | {e['confidence']} | {e['reference']['standard']}: {e['reference']['concept']} |" for e in weak]
    out += ['', f'## {n + 2}. Review points', '',
            '- **`A1.BusinessCapability` is rated medium** under the single confidence rule: its recorded source is BIAN\'s Business Capability Model with a *conceptual* alignment. ArchiMate defines Capability exactly, so re-sourcing the entity to ArchiMate would make it high.',
            '- **All 13 BIAN reference entities await validation against a licensed BIAN release**; their concepts are checked only against the public portal.',
            '- **The ArchiMate entities are confirmed as concepts, not as specification text.** Reading the ArchiMate 3.2 specification (free Open Group account) would upgrade their verification; it would not change their confidence.',
            '- **`A3.SolutionBuildingBlock` rests on TOGAF**, which is login-gated; its definition is SDEM\'s paraphrase.', '',
            '## Related', '', '- [`logical-data-model.md`](logical-data-model.md) — the Logical Data Model assembled from the entities, attributes and relationships.',
            '- [`architecture-attribute-design.md`](architecture-attribute-design.md) — the attributes of each entity type.',
            '- [`relationships-planning.md`](relationships-planning.md) — every link allowed inside each architecture.',
            '- [`inference-audit.md`](inference-audit.md) — how much of SDEM is grounded, confirmed or inferred, including the source of each attribute.',
            '- [`reference-architecture-provenance.md`](reference-architecture-provenance.md) — the standards and their public URLs.',
            '- [`architecture-metamodel-high-level-spec.md`](architecture-metamodel-high-level-spec.md) — the v0.4 entity metamodel specification this design grew from (the frozen reference); [`architecture-metamodel-detail-level-spec.md`](architecture-metamodel-detail-level-spec.md) — the governing detail-level specification.', '']
    return _terms('\n'.join(out) + '\n')


def main(argv=None):
    parser = argparse.ArgumentParser(prog='sdem-catalogue', description='Render docs/reference/architecture-entity-design.md from the entity catalogue.')
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args(argv)
    from .docmap import relink
    text = relink(render(), DOC)
    if args.check:
        ok = DOC.exists() and DOC.read_text(encoding='utf-8') == text
        print('up to date' if ok else 'STALE: regenerate with python -m sdem.catalogue'); return 0 if ok else 1
    DOC.write_text(text, encoding='utf-8'); print(f'wrote {DOC}'); return 0


if __name__ == '__main__':
    raise SystemExit(main())
